void register_ExternalInterface(py::module_& module);
void register_ExternalMarkedAsSerializable(py::module_& module);
void register_ExternalMarkedAsSerializable(py::module_& module);
void register_ExternalTypeInTypesCollection(py::module_& module);
void register_ExternalWithNoFunctions(py::module_& module);
void register_JavaExternalCtor(py::module_& module);
void register_JavaExternalTypesStruct(py::module_& module);
void register_KotlinExternalTypesStruct(py::module_& module);
