    register_ExternalTypeInTypesCollection(m);
    register_ExternalWithNoFunctions(m);
    register_JavaExternalCtor(m);
    register_JavaExternalTypesStruct(m);
    register_KotlinExternalTypesStruct(m);
    register_Month(m);
